// identifiedItemDoc is the film-item fixture for IdentifyItem (tmdb-enrichment
// D5): a tv-library item whose identifiers anchor a WRONG tmdb id and whose
// sources carry a parsed title namespace (the display name that must survive)
// plus a WRONG tmdb namespace (the one identify replaces).
func identifiedItemDoc() map[string]any {
	doc := baseDoc("Movies/Film.2019.mkv")
	doc["identifiers"] = map[string]any{"tmdb_id": int64(999)}
	doc["sources"] = map[string]any{
		"tv-parser": map[string]any{"title": "Parsed Title"},
		"tmdb":      map[string]any{"title": map[string]any{"romaji": "WRONG"}, "score": 4.65},
	}
	return doc
}

// TestIdentifyItemReanchorsAndNotifies is the item identify law (D5): the
// picked anchor OVERWRITES the previous one, the source's namespace is stripped
// and re-derived id-anchored (Match saw the picked id — the Notify proof), the
// display-name namespace stays byte-identical, and the counts read true/1/0.
func TestIdentifyItemReanchorsAndNotifies(t *testing.T) {
	ctx := context.Background()
	s, reg := queueTestStore(t)
	libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	putItem(t, s, "i_ident", libID, statusEnriched, identifiedItemDoc())
	src := &identifySrc{id: "tmdb"}
	q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{Backoff: time.Millisecond})
	q.resolve = mapResolver{"tmdb": src, "tv-parser": &succeedSrc{id: "tv-parser"}}.resolver()
	if err := q.Start(ctx); err != nil {
		t.Fatalf("Start: %v", err)
	}
	defer q.Stop()

	queued, stripped, deferred, err := q.IdentifyItem(ctx, "i_ident", "tmdb", "12345")
	if err != nil {
		t.Fatalf("IdentifyItem: %v", err)
	}
	if !queued || stripped != 1 || deferred != 0 {
		t.Fatalf("queued=%v stripped=%d deferred=%d, want true/1/0", queued, stripped, deferred)
	}

	it := waitForStatus(t, s, "i_ident", statusReady, 2*time.Second)
	d := decodeDoc(it.Document)
	ids, _ := d["identifiers"].(map[string]any)
	// decoded from the persisted JSON, the numeric anchor reads back float64;
	// the WRONG 999 must be overwritten, not merged beside.
	if ids["tmdb_id"] != float64(12345) {
		t.Fatalf("identifiers.tmdb_id = %v (%T), want 12345 (the overwritten anchor)", ids["tmdb_id"], ids["tmdb_id"])
	}
	seen := src.lastExisting()
	if seen == nil || seen["tmdb_id"] != float64(12345) {
		t.Fatalf("the re-derive's Match saw existing_ids %v, want the picked anchor 12345 (Notify + id-anchored)", seen)
	}
	fresh, _ := d["sources"].(map[string]any)["tmdb"].(map[string]any)
	if fresh["title"] != "Aria the Animation" {
		t.Fatalf("tmdb namespace not rebuilt from the picked id: %v", fresh)
	}
	parser, _ := d["sources"].(map[string]any)["tv-parser"]
	if !reflect.DeepEqual(parser, map[string]any{"title": "Parsed Title"}) {
		t.Fatalf("the display-name namespace moved during identify: %v", parser)
	}
}

// TestIdentifyItemDeferredHoldsLease pins the lease law on the item path: a
// worker-held row reports deferred 1 with NOTHING written — no anchor write,
// no strip, the document byte-identical.
func TestIdentifyItemDeferredHoldsLease(t *testing.T) {
	ctx := context.Background()
	s, reg := queueTestStore(t)
	libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	putItem(t, s, "i_hold", libID, statusEnriched, identifiedItemDoc())
	before, err := s.GetItem(ctx, "i_hold", access.System())
	if err != nil {
		t.Fatalf("GetItem: %v", err)
	}
	q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
	if !q.leases.acquire("i_hold", "worker", time.Minute) {
		t.Fatal("precondition: acquiring the live lease failed")
	}
	queued, stripped, deferred, err := q.IdentifyItem(ctx, "i_hold", "tmdb", "12345")
	if err != nil {
		t.Fatalf("IdentifyItem: %v", err)
	}
	if queued || stripped != 0 || deferred != 1 {
		t.Fatalf("queued=%v stripped=%d deferred=%d, want false/0/1", queued, stripped, deferred)
	}
	after, err := s.GetItem(ctx, "i_hold", access.System())
	if err != nil {
		t.Fatalf("GetItem after: %v", err)
	}
	if string(before.Document) != string(after.Document) {
		t.Fatalf("a lease-held row must stay byte-identical:\nbefore %s\nafter  %s", before.Document, after.Document)
	}
}

// TestIdentifyItemUnknownRow pins the 404 law: an unknown row id surfaces
// sql.ErrNoRows (the api maps it to 404), and a loaded source in the resolver
// proves the error is the row lookup, not plugin resolution. The store's other
// rows stay untouched.
func TestIdentifyItemUnknownRow(t *testing.T) {
	ctx := context.Background()
	s, reg := queueTestStore(t)
	libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	putItem(t, s, "i_real", libID, statusEnriched, identifiedItemDoc())
	before, err := s.GetItem(ctx, "i_real", access.System())
	if err != nil {
		t.Fatalf("GetItem: %v", err)
	}
	q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
	q.resolve = mapResolver{"tmdb": &identifySrc{id: "tmdb"}}.resolver()

	_, _, _, err = q.IdentifyItem(ctx, "item_missing", "tmdb", "12345")
	if err == nil {
		t.Fatal("an unknown row must error")
	}
	if !errors.Is(err, sql.ErrNoRows) {
		t.Fatalf("err = %v, want sql.ErrNoRows preserved (the api's 404)", err)
	}
	after, gerr := s.GetItem(ctx, "i_real", access.System())
	if gerr != nil {
		t.Fatalf("GetItem after: %v", gerr)
	}
	if string(before.Document) != string(after.Document) {
		t.Fatalf("an unknown row must write nothing:\nbefore %s\nafter  %s", before.Document, after.Document)
	}
}
